cc.Class({
    extends: cc.Component,
    properties: {
        itemTemplate: cc.Node,
        layoutParent: cc.Node,
    },
    onLoad: function () {
        cc.BacaratController.getInstance().setSoiCau2View(this);
        this.itemPool = new cc.NodePool();
        for (let i = 0; i < 72; i++) {
            this.itemPool.put(cc.instantiate(this.itemTemplate));
        }
        this.layoutParent.width = 380;
        //this.clearList();
        //this.node.active = false;
    },
    initListSoiCau2: function (data) {
        if (data.length === 0) {
            return;
        }
        try {
            this.clearList();
        } catch (e) {
            console.log(e);
        }
        
        data = data.slice(0,72);
        data.map(gate => {
            let item = null;
            if(this.itemPool.size() > 0) {
                item = this.itemPool.get();
            }else {
                item = cc.instantiate(this.itemTemplate);
            }
            item.getComponent(cc.ItemSoiCau).setSpiteFrameItem(gate.BigGateIDWin, gate.IsPlayerPair, gate.IsBankerPair,1,true);
            //item.node.setScale(v2(1.5,1.5));
            item.parent = this.layoutParent;
        }, this);
        this.node.active = true;
    },
    clearList: function () {
        let nodes = this.layoutParent.children;
        if(nodes.length > 0) {
            nodes.map(item => {
                this.itemPool.put(item);
            }, this);
        }
        this.layoutParent.removeAllChildren(true);
    },
    onDestroy: function () {
        try {
            this.itemPool.clear();
        } catch (e) {

        }
    }
});
